from urllib import request as urllib_request

def fetch_url_content(host, path):
    '''
    An asynchronous function to fetch content from a given URL using the requests library.

    This function ensures that the central server is not overloaded by making use of asynchronous requests.
    '''

    # Validate the host and path
    if not host or not path:
        raise ValueError("Host and path must be provided.")

    # Use the requests library to make an asynchronous GET request
    try:
        response = urllib_request.urlopen(f"{host}{path}")
        return response.read()
