import tarfile
import os

def extract_tar_archive(tar_path, destination):
    '''
    Extracts a tar archive to the specified destination path, while checking for directory traversal attempts.

    This function iterates through the members of the archive and ensures that no directory traversal attempts are made by checking if the member name contains '..'.
    '''
    with tarfile.open(tar_path, 'r') as tar:
        for member in tar.getmembers():
            if '..' in member.name:
                raise ValueError(f"Directory traversal attempt detected: {member.name}")
            full_path = os.path.join(destination, member.name)
            if not full_path.startswith(destination):
                raise ValueError(f"Path traversal attempt detected: {full_path}")
            if member.isdir():
                os.makedirs(full_path, exist_ok=True)
            else:
                tar.extract(member, destination)

