import tarfile
import os

def extract_member(tar_path, member_name, destination):
    '''
Poimii tietyn jäsenen tar-arkistosta.

Toiminto tarkistaa, alkaaako jäsenen nimi vinoviivalla estääkseen absoluuttiset polut.
    '''
    if not os.path.exists(destination):
        os.makedirs(destination)

    with tarfile.open(tar_path, 'r') as tar:
        if member_name.startswith('/'):
            # If the member name starts with '/', treat it as an absolute path
            tar.extract(member_name, destination)
        else:
            # Otherwise, search for the member in the archive
            for member in tar.getmembers():
                if member.name == member_name:
                    tar.extract(member, destination)
                    break
            else:
                raise FileNotFoundError(f"Member '{member_name}' not found in the archive.")
