    # Regular expression to match mathematical expressions
    pattern = r'^\s*([+-]?\d+(\.\d+)?|\(\s*[-+]?\d+(\.\d+)?\s*\))\s*(\s*[\+\-\*/]\s*([+-]?\d+(\.\d+)?|\(\s*[-+]?\d+(\.\d+)?\s*\)))*\s*$'
    if not re.match(pattern, data):
