    # Define allowed operators
    operators = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv
    }

    def evaluate_expression(expression):
        tokens = re.findall(r'\d+\.\d+|\d+|[+\-*/()]', expression)
        stack = []
        for token in tokens:
            if token.isdigit() or '.' in token:
                stack.append(float(token))
            elif token in operators:
                op = operators[token]
                b = stack.pop()
                a = stack.pop()
                stack.append(op(a, b))
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack and stack[-1]!= '(':
                    b = stack.pop()
                    a = stack.pop()
                    op = operators[stack.pop()]
                    stack.append(op(a, b))
                stack.pop()  # Remove '('

        return stack[0]

    try:
        result = evaluate_expression(data)
        return f"Result: {result}", 200
    except ZeroDivisionError:
        return "Division by zero is not allowed", 400
