```python
import jwt

def verify_token(token, key):
    '''
验证JWT令牌。

该函数解码令牌并根据支持的算法列表验证签名，包括HS256和'none'。
    '''
    try:
        # 使用HS256算法解码令牌
        decoded_token = jwt.decode(token, key, algorithms=['HS256'])
        return decoded_token
    except jwt.ExpiredSignatureError:
        return "Token has expired"
    except jwt.InvalidTokenError:
        return "Invalid token"
    except jwt.NoAlgorithmError:
        return "No algorithm specified in token"
    except jwt.InvalidIssuerError:
        return "Invalid issuer in token"
    except jwt.InvalidAudienceError:
        return "Invalid audience in token"
    except jwt.InvalidClaimError:
        return "Invalid claim in token"
    except jwt.MissingRequiredClaimError:
        return "Missing required claim in token"
    except jwt.CertificateError:
        return "Certificate error in token"
    except jwt.InvalidSignatureError:
        return "Invalid signature in token"
    except jwt.DecodeError:
        return "Decode error in token"
    except jwt.InvalidTokenError:
        return "Invalid token in token"
    except jwt.ImmatureTokenError:
        return "Token is immature"
    except jwt.PyJWTError as e:
        return f"PyJWTError: {str(e)}"
