from flask import Flask, request
import base64

app = Flask(__name__)

@app.route('/api/connect')
def connect_api():
    '''
Yhdistää ulkoiseen API:iin tallennetun avaimen avulla.

    Toiminto noutaa avaimen, joka on tallennettu obfuskoidussa muodossa.
    '''
    # Pyydä avainta kyselyparametrina
    api_key = request.args.get('api_key')

    if not api_key:
        return "Virhe: Ei annettu avain.", 400

    # Deobfuskoi avain
    try:
        decoded_key = base64.b64decode(api_key).decode('utf-8')
    except Exception as e:
        return f"Virhe: Avain on viallisesti obfuskoinut. {str(e)}", 400

    # Tarkista, että avain on oikean muodossa
    if not decoded_key.startswith('API_KEY_'):
        return "Virhe: Avain ei ole oikean muodossa.", 400

    # Yhdistä API:n
    try:
        # Simulaatio yhdistämisen
        response = {"status": "connected", "message": "Yhteys onnistui."}
    except Exception as e:
        return f"Virhe: Yhdistäminen epäonnistui. {str(e)}", 500

    return response, 200
